import { app } from 'electron'
import { mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { basename, join } from 'node:path'
import type { ThemeInfo } from '../shared/types'
import { dataDir } from './config'

/**
 * The theme library: Zellamp's bundled skins (generated by `npm run themes`)
 * plus any .wsz the user installs, which are copied into the app support dir.
 *
 * Ids: bundled themes use their manifest id ('neon-arcade'); installed ones
 * are 'user:<file name>'.
 */

const USER_PREFIX = 'user:'
const SKIN_FILE = /\.(wsz|zip|svg)$/i
const isFreeformFile = (file: string) => /\.svg$/i.test(file)

interface ManifestEntry {
  id: string
  name: string
  description: string
  file: string
  kind?: ThemeInfo['kind']
  panel?: string
}

function bundledDir() {
  return app.isPackaged ? join(process.resourcesPath, 'themes') : join(app.getAppPath(), 'resources/themes')
}

export function userThemesDir() {
  const dir = join(dataDir(), 'themes')
  mkdirSync(dir, { recursive: true })
  return dir
}

// Read fresh each time: it's tiny, and `npm run skins` updates it during dev.
function manifest(): ManifestEntry[] {
  try {
    return JSON.parse(readFileSync(join(bundledDir(), 'themes.json'), 'utf8'))
  } catch (err) {
    console.warn('[themes] no bundled themes manifest:', String(err))
    return []
  }
}

/** "my_cool-skin.wsz" → "My Cool Skin" */
function prettyName(file: string) {
  return file
    .replace(SKIN_FILE, '')
    .replace(/[_\-.]+/g, ' ')
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase())
}

export function listThemes(): ThemeInfo[] {
  const bundled: ThemeInfo[] = manifest().map((m) => ({
    id: m.id,
    name: m.name,
    description: m.description,
    source: m.id === 'classic' ? 'builtin' : 'zellamp',
    kind: m.kind ?? 'classic',
    panel: m.panel,
  }))
  const dir = userThemesDir()
  const installed: ThemeInfo[] = readdirSync(dir)
    .filter((f) => SKIN_FILE.test(f))
    .map((f) => ({ f, mtime: statSync(join(dir, f)).mtimeMs }))
    .sort((a, b) => b.mtime - a.mtime)
    .map(({ f }) => ({
      id: USER_PREFIX + f,
      name: prettyName(f),
      description: f,
      source: 'installed' as const,
      kind: isFreeformFile(f) ? ('freeform' as const) : ('classic' as const),
    }))
  return [...bundled, ...installed]
}

export function themeExists(id: string) {
  return listThemes().some((t) => t.id === id)
}

export function themeInfo(id: string) {
  return listThemes().find((t) => t.id === id) ?? null
}

export function readTheme(id: string): Uint8Array | null {
  try {
    if (id.startsWith(USER_PREFIX)) {
      return new Uint8Array(readFileSync(join(userThemesDir(), basename(id.slice(USER_PREFIX.length)))))
    }
    const entry = manifest().find((m) => m.id === id)
    return entry ? new Uint8Array(readFileSync(join(bundledDir(), entry.file))) : null
  } catch {
    return null
  }
}

/**
 * Cheap sanity check before a skin reaches Webamp: a zip whose directory
 * lists a main.bmp. (File names in a zip are stored uncompressed.)
 */
function looksLikeSkin(data: Uint8Array) {
  const zipMagic = data[0] === 0x50 && data[1] === 0x4b && data[2] === 0x03 && data[3] === 0x04
  return zipMagic && Buffer.from(data).toString('latin1').toLowerCase().includes('main.bmp')
}

/** A Zellamp freeform skin: an SVG with data-za bindings. */
function looksLikeFreeform(data: Uint8Array) {
  const text = Buffer.from(data).toString('utf8')
  return /<svg[\s>]/i.test(text) && text.includes('data-za=')
}

/**
 * Copies a skin into the library and returns its id. Re-installing the same
 * file name replaces it. Throws with a user-facing message if it isn't a skin.
 */
export function installTheme(name: string, data: Uint8Array): string {
  const file = basename(name).replace(/[^\w.\- ]/g, '_')
  if (!SKIN_FILE.test(file)) throw new Error(`${name} isn't a .wsz or Zellamp .svg skin.`)
  if (isFreeformFile(file)) {
    if (!looksLikeFreeform(data)) throw new Error(`${name} isn't a Zellamp freeform skin (no data-za bindings).`)
  } else if (!looksLikeSkin(data)) throw new Error(`${name} doesn't look like a Winamp 2 skin (no main.bmp inside).`)
  writeFileSync(join(userThemesDir(), file), data)
  return USER_PREFIX + file
}

/** Only installed themes can be removed. */
export function removeTheme(id: string): boolean {
  if (!id.startsWith(USER_PREFIX)) return false
  rmSync(join(userThemesDir(), basename(id.slice(USER_PREFIX.length))), { force: true })
  return true
}
